from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()

@app.vibe("/vibe")
def read_vibe():
    return {"message": "vibe check passed"}

client = TestClient(app)

def test_vibe():
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibe check passed"}

if __name__ == "__main__":
    try:
        test_vibe()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
